from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump = {a: b for a, b in jumps}

    def resolve(q):
        while q in jump:
            q = jump[q]
        return q

    # Transitions from each non-terminal cell, one entry per die face.
    trans = {}
    for p in range(n):
        dests = []
        for r in range(1, m + 1):
            q = p + r
            if q > n:
                q = 2 * n - q
            dests.append(resolve(q))
        trans[p] = dests

    # Cells reachable from the start without passing through the terminal cell.
    reach = {0}
    stack = [0]
    while stack:
        p = stack.pop()
        for q in trans[p]:
            if q != n and q not in reach:
                reach.add(q)
                stack.append(q)

    # Cells that can reach the terminal cell n, found by a reverse search.
    rev = {i: [] for i in range(n)}
    for p in range(n):
        for q in trans[p]:
            if q != n:
                rev[q].append(p)
    good = set()
    stack = [p for p in range(n) if any(q == n for q in trans[p])]
    good.update(stack)
    while stack:
        q = stack.pop()
        for p in rev[q]:
            if p not in good:
                good.add(p)
                stack.append(p)

    # If the token can get stuck somewhere it cannot leave, the game may never end.
    if any(p not in good for p in reach):
        return None

    # Solve E[p] = 1 + (1/m) * sum E[q] over reachable non-terminal states.
    idx = sorted(reach)
    pos = {p: i for i, p in enumerate(idx)}
    k = len(idx)
    A = [[Fraction(0)] * k for _ in range(k)]
    b = [Fraction(1)] * k
    for i, p in enumerate(idx):
        A[i][i] += 1
        for q in trans[p]:
            if q != n:
                A[i][pos[q]] -= Fraction(1, m)

    # Gauss-Jordan elimination with exact fractions.
    for col in range(k):
        piv = next(r for r in range(col, k) if A[r][col] != 0)
        A[col], A[piv] = A[piv], A[col]
        b[col], b[piv] = b[piv], b[col]
        inv = 1 / A[col][col]
        A[col] = [v * inv for v in A[col]]
        b[col] *= inv
        for r in range(k):
            if r != col and A[r][col] != 0:
                f = A[r][col]
                A[r] = [x - f * y for x, y in zip(A[r], A[col])]
                b[r] -= f * b[col]

    ans = b[pos[0]]
    return [ans.numerator, ans.denominator]
